import functools

def _parse(v):
    core = v.split('+', 1)[0]
    if '-' in core:
        main, pre = core.split('-', 1)
    else:
        main, pre = core, None
    major, minor, patch = (int(x) for x in main.split('.'))
    return (major, minor, patch, pre)

def _cmp_pre(a, b):
    if a is None and b is None:
        return 0
    if a is None:
        return 1
    if b is None:
        return -1
    a_ids = a.split('.')
    b_ids = b.split('.')
    for x, y in zip(a_ids, b_ids):
        x_num = x.isdigit()
        y_num = y.isdigit()
        if x_num and y_num:
            xi, yi = int(x), int(y)
            if xi != yi:
                return -1 if xi < yi else 1
        elif x_num and not y_num:
            return -1
        elif not x_num and y_num:
            return 1
        else:
            if x != y:
                return -1 if x < y else 1
    if len(a_ids) != len(b_ids):
        return -1 if len(a_ids) < len(b_ids) else 1
    return 0

def _cmp(v1, v2):
    a = _parse(v1)
    b = _parse(v2)
    if a[0] != b[0]:
        return -1 if a[0] < b[0] else 1
    if a[1] != b[1]:
        return -1 if a[1] < b[1] else 1
    if a[2] != b[2]:
        return -1 if a[2] < b[2] else 1
    return _cmp_pre(a[3], b[3])

def semver_sort(versions):
    return sorted(versions, key=functools.cmp_to_key(_cmp))

